// ROUTE: deterministic code, not the model. AI perceives, code decides.
const URGENT_MIN = 0.7;
const item = $input.first().json;
const prep = $('Prepare Ticket').first().json;
const a = item.answers || {};
const urgent = a.urgent?.noul;
const team = a.team?.choice;
const conf = a.team?.confidence;
const ok = ['infra', 'billing', 'sales'].includes(team)
  && [urgent, conf].every(v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1);
const route_if_trusted = !ok ? null : (urgent >= URGENT_MIN ? 'page_oncall:' + team : 'queue:' + team);
return [{ json: {
  ticket: prep.ticket, expected_team: prep.expected_team, started_at: prep.started_at,
  classify_ok: ok,
  urgent: ok ? urgent : null, team: ok ? team : null, confidence: ok ? conf : 0,
  route_if_trusted,
  classify_latency_ms: Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : null,
  classify_output_tokens: item.usage?.output_tokens ?? null
} }];

// RANK: every answer carries a calibrated confidence. Bands are demo cut-offs.
// Optional compact scoring: send expected_team and we mark the answer right or wrong.
const d = $input.first().json;
const band = !d.classify_ok ? 'none' : d.confidence >= 0.8 ? 'high' : d.confidence >= 0.6 ? 'medium' : 'low';
const team_correct = (d.expected_team && d.classify_ok) ? d.team === d.expected_team : null;
return [{ json: { ...d, confidence_band: band, team_correct } }];

// GATE passed: confidence >= 0.6, so System 1's answer stands. No System 2 call.
const d = $('Rank').first().json;
return [{ json: {
  ticket: d.ticket,
  final_route: d.route_if_trusted,
  decided_by: 'System 1 (Laya)',
  stages: {
    classify: { urgent: d.urgent, team: d.team, latency_ms: d.classify_latency_ms, output_tokens: d.classify_output_tokens },
    route: { route_if_trusted: d.route_if_trusted, rule: 'urgent >= 0.7 pages on-call, else team queue' },
    rank: { confidence: d.confidence, band: d.confidence_band, expected_team: d.expected_team, team_correct: d.team_correct },
    gate: { threshold: 0.6, passed: true, sent_to_human: false },
    choose: { escalated_to_system_2: false }
  },
  total_ms: Date.now() - d.started_at,
  note: 'Demo labels only: no page or queue action is executed.'
} }];

// CHOOSE result: System 2 answers. Gate again: still unsure or unusable -> human_review.
const d = $('Rank').first().json;
const item = $input.first().json;
let s2 = null;
try {
  const raw = String(item.response ?? '').replace(/```(?:json)?/gi, '').trim();
  s2 = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  if (!['infra', 'billing', 'sales'].includes(s2.team)
    || ![s2.urgent, s2.confidence].every(v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)) s2 = null;
} catch (_) { s2 = null; }
let final_route = 'human_review', decided_by = 'human (System 2 unsure or unavailable)';
if (s2 && s2.confidence >= 0.6) {
  final_route = (s2.urgent >= 0.7 ? 'page_oncall:' : 'queue:') + s2.team;
  decided_by = 'System 2 (Ollama)';
}
const team_correct_s2 = (d.expected_team && s2) ? s2.team === d.expected_team : null;
return [{ json: {
  ticket: d.ticket,
  final_route,
  decided_by,
  stages: {
    classify: { urgent: d.urgent, team: d.team, latency_ms: d.classify_latency_ms, output_tokens: d.classify_output_tokens, usable: d.classify_ok },
    route: { route_if_trusted: d.route_if_trusted },
    rank: { confidence: d.confidence, band: d.confidence_band, expected_team: d.expected_team, team_correct: d.team_correct },
    gate: { threshold: 0.6, passed: false, note: 'System 1 below 0.6, so it does not decide' },
    choose: {
      escalated_to_system_2: true,
      system_2: s2 ? { urgent: s2.urgent, team: s2.team, confidence: s2.confidence, team_correct: team_correct_s2 } : null,
      system_2_latency_ms: Math.round((item.total_duration || 0) / 1e6),
      system_2_output_tokens: item.eval_count ?? null,
      system_2_usable: !!s2
    }
  },
  total_ms: Date.now() - d.started_at,
  note: 'Demo labels only: no page or queue action is executed.'
} }];
